  public void handle(Context context) {
    if (absolute) {
      context.insert(handlers, FileSystemBinding.class, absoluteBinding);
    } else {
      FileSystemBinding parentBinding = context.maybeGet(FileSystemBinding.class);
      if (parentBinding == null) {
        context.insert(handlers, FileSystemBinding.class, absoluteBinding);
      } else {
        FileSystemBinding binding = parentBinding.binding(file.getPath());
        context.insert(handlers, FileSystemBinding.class, binding);
      }
    }
  }
}

